using System;
using System.IO;
using System.Security.Claims;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.Processing;
using SixLabors.ImageSharp.Formats.Png;

namespace ImagePipeline.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ImageController : ControllerBase
    {
        private const int MaxDimension = 8192;
        private const int BaseStackReserve = 1024 * 1024; // 1MB
        private const long MaxFileSize = 50 * 1024 * 1024; // 50MB

        private readonly IAuthorizationService _authService;
        private readonly IImageProcessingService _processor;

        public ImageController(IAuthorizationService authService, IImageProcessingService processor)
        {
            _authService = authService;
            _processor = processor;
        }

        [HttpPost("transform")]
        [Authorize]
        public async Task<IActionResult> TransformImage([FromForm] ImageTransformRequest request)
        {
            if (request.File == null || request.File.Length == 0)
                return BadRequest("No file provided");

            if (request.File.Length > MaxFileSize)
                return BadRequest("File too large");

            var authResult = await _authService.AuthorizeAsync(User, null, "ImageProcessing");
            if (!authResult.Succeeded)
                return Forbid();

            var tierLimit = GetProcessingTier(User);
            var computeBudget = ComputeResourceBudget(request, tierLimit);

            using var stream = request.File.OpenReadStream();
            var result = await _processor.ProcessAsync(stream, request, computeBudget);

            return File(result, "image/png", "output.png");
        }

        private ProcessingTier GetProcessingTier(ClaimsPrincipal user)
        {
            if (user.IsInRole("Admin"))
                return ProcessingTier.Unlimited;
            if (user.IsInRole("Premium"))
                return ProcessingTier.High;
            return ProcessingTier.Standard;
        }

        private ResourceBudget ComputeResourceBudget(ImageTransformRequest request, ProcessingTier tier)
        {
            int maxRecursionDepth = tier switch
            {
                ProcessingTier.Unlimited => 256,
                ProcessingTier.High => 64,
                ProcessingTier.Standard => 16,
                _ => 8
            };

            // Stack budget calculation based on tier and requested operations
            int operationCount = request.Operations?.Length ?? 0;
            long stackBudget = CalculateStackRequirement(operationCount, maxRecursionDepth, tier);

            return new ResourceBudget
            {
                MaxRecursionDepth = maxRecursionDepth,
                StackBudget = stackBudget,
                MaxPixelCount = tier == ProcessingTier.Unlimited ? long.MaxValue : 4096L * 4096L
            };
        }

        private long CalculateStackRequirement(int operations, int maxDepth, ProcessingTier tier)
        {
            // Each recursive filter operation uses a frame on the stack
            // Frame size varies by operation complexity
            long frameSize = 4096; // base frame size
            long totalRequired = (long)operations * maxDepth * frameSize;

            // Apply tier-based multiplier for nested convolution kernels
            int tierMultiplier = tier == ProcessingTier.Unlimited ? 1 : 2;
            totalRequired = totalRequired * tierMultiplier;

            // Ensure we don't exceed platform stack limit
            long platformLimit = GetPlatformStackLimit();
            return Math.Min(totalRequired, platformLimit);
        }

        private long GetPlatformStackLimit()
        {
            // On Linux/.NET, default thread stack is 8MB
            // We reserve BaseStackReserve for framework overhead
            return (8 * 1024 * 1024) - BaseStackReserve;
        }
    }

    public interface IImageProcessingService
    {
        Task<byte[]> ProcessAsync(Stream input, ImageTransformRequest request, ResourceBudget budget);
    }

    public class ImageProcessingService : IImageProcessingService
    {
        private const int MaxKernelSize = 15; // Safe maximum kernel dimension
        private const int MaxTotalDepth = 32; // Absolute recursion cap regardless of tier

        public async Task<byte[]> ProcessAsync(Stream input, ImageTransformRequest request, ResourceBudget budget)
        {
            using var image = await Image.LoadAsync(input);

            if ((long)image.Width * image.Height > budget.MaxPixelCount)
                throw new InvalidOperationException("Image exceeds pixel budget");

            int effectiveMaxDepth = Math.Min(budget.MaxRecursionDepth, MaxTotalDepth);

            foreach (var op in request.Operations ?? Array.Empty<TransformOperation>())
            {
                ApplyOperation(image, op, effectiveMaxDepth, 0, budget);
            }

            using var output = new MemoryStream();
            await image.SaveAsync(output, new PngEncoder());
            return output.ToArray();
        }

        private void ApplyOperation(Image image, TransformOperation op, int maxDepth, int currentDepth, ResourceBudget budget)
        {
            if (currentDepth >= maxDepth)
                return;

            // Allocate kernel buffer on HEAP to avoid stack pressure
            // Size is strictly clamped to safe maximum
            int kernelSize = Math.Clamp(op.KernelSize, 3, MaxKernelSize);
            float[] kernel = new float[kernelSize * kernelSize];
            InitializeKernel(kernel, op.FilterType);

            switch (op.Type)
            {
                case OperationType.Blur:
                    image.Mutate(x => x.GaussianBlur(Math.Clamp(op.Radius, 0.1f, 50f)));
                    break;
                case OperationType.Sharpen:
                    image.Mutate(x => x.GaussianSharpen(Math.Clamp(op.Radius, 0.1f, 50f)));
                    break;
                case OperationType.Recursive:
                    // Apply nested operations - each level adds stack frames
                    if (op.SubOperations != null)
                    {
                        foreach (var subOp in op.SubOperations)
                        {
                            ApplyOperation(image, subOp, maxDepth, currentDepth + 1, budget);
                        }
                    }
                    break;
            }
        }

        private void InitializeKernel(float[] kernel, FilterType filterType)
        {
            float value = filterType switch
            {
                FilterType.Identity => 0f,
                FilterType.Edge => -1f,
                FilterType.Emboss => 2f,
                _ => 1f / kernel.Length
            };
            Array.Fill(kernel, value);
            if (filterType == FilterType.Identity && kernel.Length > 0)
                kernel[kernel.Length / 2] = 1f;
        }
    }

    public class ImageTransformRequest
    {
        public Microsoft.AspNetCore.Http.IFormFile File { get; set; }
        public TransformOperation[] Operations { get; set; }
    }

    public class TransformOperation
    {
        public OperationType Type { get; set; }
        public int KernelSize { get; set; }
        public float Radius { get; set; }
        public FilterType FilterType { get; set; }
        public TransformOperation[] SubOperations { get; set; }
    }

    public class ResourceBudget
    {
        public int MaxRecursionDepth { get; set; }
        public long StackBudget { get; set; }
        public long MaxPixelCount { get; set; }
    }

    public enum ProcessingTier { Standard, High, Unlimited }
    public enum OperationType { Blur, Sharpen, Recursive }
    public enum FilterType { Identity, Edge, Emboss, Box }
}
